import json
import re
import sys
from collections import Counter, defaultdict

import anndata as ad
import numpy as np
import pandas as pd


TARGETS = ["PABPC1", "NUDT21", "LEO1"]


def clean_value(value):
    if pd.isna(value):
        return None
    text = str(value).strip()
    if text == "" or text.lower() in {"nan", "none", "null", "na"}:
        return None
    return text


def split_tokens(value):
    text = clean_value(value)
    if text is None:
        return []
    parts = re.split(r"[;,|/+]", text)
    out = []
    for part in parts:
        token = part.strip()
        if token:
            out.append(token)
    return out or [text]


def norm_gene(value):
    text = clean_value(value)
    if text is None:
        return None
    return text.upper()


def summarize_adata(name, a):
    lines = []
    lines.append(f"[{name}] shape: n_obs={a.n_obs}, n_vars={a.n_vars}")
    lines.append(f"[{name}] obs columns: {list(a.obs.columns)}")
    lines.append(f"[{name}] var columns: {list(a.var.columns)}")
    lines.append(f"[{name}] uns keys: {list(a.uns.keys())}")
    for axis_name, df in [("obs", a.obs), ("var", a.var)]:
        for col in df.columns:
            s = df[col]
            n = int(s.nunique(dropna=True))
            if n <= 30 or any(key in col.lower() for key in ["guide", "grna", "target", "gene", "perturb"]):
                vals = [str(x) for x in s.dropna().astype(str).unique()[:30]]
                lines.append(f"[{name}] {axis_name}.{col}: nunique={n}; sample={vals}")
    return lines


def find_gene_columns(df):
    candidates = []
    for col in df.columns:
        col_l = col.lower()
        values = {norm_gene(v) for v in df[col].dropna().astype(str).unique()[:100000]}
        hit_count = sum(t in values for t in TARGETS)
        if hit_count:
            score = 100 + hit_count * 10
            if any(k in col_l for k in ["target", "gene", "symbol"]):
                score += 20
            candidates.append((score, col, hit_count))
    return sorted(candidates, reverse=True)


def find_guide_columns(df):
    candidates = []
    for col in df.columns:
        col_l = col.lower()
        if any(k in col_l for k in ["guide", "grna", "sgrna", "protospacer", "perturb"]):
            n = int(df[col].nunique(dropna=True))
            if n > 1:
                score = 100
                if "guide" in col_l or "grna" in col_l:
                    score += 30
                if "target" in col_l or "gene" in col_l:
                    score -= 20
                candidates.append((score, col, n))
    return sorted(candidates, reverse=True)


def pair_from_obs(ref_obs, guide_col, gene_col):
    counts = defaultdict(Counter)
    for guide_raw, gene_raw in zip(ref_obs[guide_col], ref_obs[gene_col]):
        gene = norm_gene(gene_raw)
        if gene not in TARGETS:
            continue
        for guide in split_tokens(guide_raw):
            if norm_gene(guide) == gene:
                continue
            counts[gene][guide] += 1
    return counts


def pair_from_var(ref_var, guide_col, gene_col):
    counts = defaultdict(Counter)
    for guide_raw, gene_raw in zip(ref_var[guide_col], ref_var[gene_col]):
        gene = norm_gene(gene_raw)
        if gene not in TARGETS:
            continue
        for guide in split_tokens(guide_raw):
            if norm_gene(guide) == gene:
                continue
            counts[gene][guide] += 1
    return counts


def merge_counts(dest, src):
    for gene, counter in src.items():
        dest[gene].update(counter)


def choose_guides(counts):
    answer = []
    details = {}
    for gene in TARGETS:
        if gene not in counts or not counts[gene]:
            raise RuntimeError(f"No guide mapping found for {gene}")
        ranked = counts[gene].most_common()
        best_count = ranked[0][1]
        tied = [guide for guide, count in ranked if count == best_count]
        if len(tied) != 1:
            raise RuntimeError(f"Ambiguous guide mapping for {gene}: {ranked[:10]}")
        answer.append(tied[0])
        details[gene] = ranked[:10]
    return answer, details


def main():
    ref_path, query_path, answer_path, diag_path = sys.argv[1:5]
    ref = ad.read_h5ad(ref_path)
    query = ad.read_h5ad(query_path)

    diag = []
    diag.extend(summarize_adata("ref", ref))
    diag.extend(summarize_adata("query", query))

    all_counts = defaultdict(Counter)
    obs_gene_cols = find_gene_columns(ref.obs)
    obs_guide_cols = find_guide_columns(ref.obs)
    var_gene_cols = find_gene_columns(ref.var)
    var_guide_cols = find_guide_columns(ref.var)
    diag.append(f"ref obs gene column candidates: {obs_gene_cols}")
    diag.append(f"ref obs guide column candidates: {obs_guide_cols}")
    diag.append(f"ref var gene column candidates: {var_gene_cols}")
    diag.append(f"ref var guide column candidates: {var_guide_cols}")

    for _, guide_col, _ in obs_guide_cols:
        for _, gene_col, _ in obs_gene_cols:
            counts = pair_from_obs(ref.obs, guide_col, gene_col)
            if counts:
                diag.append(f"obs pairing guide={guide_col} gene={gene_col}: {dict((g, c.most_common(10)) for g, c in counts.items())}")
                merge_counts(all_counts, counts)

    for _, guide_col, _ in var_guide_cols:
        for _, gene_col, _ in var_gene_cols:
            counts = pair_from_var(ref.var, guide_col, gene_col)
            if counts:
                diag.append(f"var pairing guide={guide_col} gene={gene_col}: {dict((g, c.most_common(10)) for g, c in counts.items())}")
                merge_counts(all_counts, counts)

    # Also inspect unstructured annotations that may store guide-to-target tables.
    for key, value in ref.uns.items():
        if isinstance(value, pd.DataFrame):
            gene_cols = find_gene_columns(value)
            guide_cols = find_guide_columns(value)
            diag.append(f"ref uns.{key} dataframe columns={list(value.columns)} gene_candidates={gene_cols} guide_candidates={guide_cols}")
            for _, guide_col, _ in guide_cols:
                for _, gene_col, _ in gene_cols:
                    counts = pair_from_var(value, guide_col, gene_col)
                    if counts:
                        diag.append(f"uns pairing key={key} guide={guide_col} gene={gene_col}: {dict((g, c.most_common(10)) for g, c in counts.items())}")
                        merge_counts(all_counts, counts)
        elif isinstance(value, dict):
            diag.append(f"ref uns.{key} dict keys={list(value.keys())[:30]}")

    answer, details = choose_guides(all_counts)

    query_guides = set()
    for _, col, _ in find_guide_columns(query.obs):
        for val in query.obs[col].dropna().astype(str).unique():
            query_guides.update(split_tokens(val))
    for _, col, _ in find_guide_columns(query.var):
        for val in query.var[col].dropna().astype(str).unique():
            query_guides.update(split_tokens(val))
    if query_guides:
        presence = {guide: guide in query_guides for guide in answer}
        diag.append(f"answer guide presence in query guide-like columns: {presence}")

    diag.append(f"selected mapping: {json.dumps(details, sort_keys=True)}")
    with open(answer_path, "w") as handle:
        handle.write(",".join(answer) + "\n")
    with open(diag_path, "w") as handle:
        handle.write("\n".join(diag) + "\n")


if __name__ == "__main__":
    main()

