import json
import re
import sys
from collections import defaultdict

import h5py
import numpy as np
import pandas as pd
import scipy.sparse as sp
from scipy.optimize import linear_sum_assignment


TARGETS = ["PABPC1", "NUDT21", "LEO1"]


def decode_scalar(value):
    if isinstance(value, (bytes, np.bytes_)):
        return bytes(value).decode("utf-8")
    return value


def decode_array(values):
    arr = np.asarray(values)
    if arr.dtype.kind == "S":
        return np.array([decode_scalar(x) for x in arr], dtype=object)
    if arr.dtype.kind == "O":
        return np.array([decode_scalar(x) for x in arr], dtype=object)
    return arr


def read_node(node):
    if isinstance(node, h5py.Dataset):
        return decode_array(node[()])
    enc = decode_scalar(node.attrs.get("encoding-type", ""))
    if enc == "categorical":
        codes = np.asarray(node["codes"][()])
        categories = decode_array(node["categories"][()])
        out = []
        for code in codes:
            out.append(np.nan if code < 0 else categories[int(code)])
        return np.asarray(out, dtype=object)
    if enc in {"nullable-string", "nullable-integer", "nullable-boolean"}:
        values = decode_array(node["values"][()])
        if "mask" in node:
            values = values.astype(object)
            values[np.asarray(node["mask"][()]).astype(bool)] = np.nan
        return values
    if "values" in node and isinstance(node["values"], h5py.Dataset):
        return decode_array(node["values"][()])
    raise TypeError(f"Unsupported node {node.name} encoding={enc}")


def attr_list(attrs, name):
    value = attrs.get(name, [])
    if isinstance(value, (str, bytes, np.bytes_)):
        return [decode_scalar(value)]
    return [decode_scalar(x) for x in list(value)]


def read_dataframe(group):
    columns = attr_list(group.attrs, "column-order")
    data = {}
    for col in columns:
        if col in group:
            data[col] = read_node(group[col])
    if not data:
        for key in group.keys():
            try:
                values = read_node(group[key])
            except Exception:
                continue
            if np.asarray(values).ndim == 1:
                data[key] = values
    return pd.DataFrame({k: np.asarray(v, dtype=object) for k, v in data.items()})


def read_matrix(node):
    if isinstance(node, h5py.Dataset):
        return np.asarray(node[()], dtype=np.float64)
    enc = decode_scalar(node.attrs.get("encoding-type", ""))
    shape = tuple(int(x) for x in node.attrs["shape"])
    data = np.asarray(node["data"][()], dtype=np.float64)
    indices = np.asarray(node["indices"][()])
    indptr = np.asarray(node["indptr"][()])
    if enc in {"csr_matrix", "csr"}:
        return sp.csr_matrix((data, indices, indptr), shape=shape)
    if enc in {"csc_matrix", "csc"}:
        return sp.csc_matrix((data, indices, indptr), shape=shape).tocsr()
    raise TypeError(f"Unsupported matrix {node.name} encoding={enc}")


def clean_string(value):
    if pd.isna(value):
        return ""
    return str(decode_scalar(value)).strip()


def is_nt(guide):
    return clean_string(guide).upper().startswith("NT-")


def matrix_stats(matrix):
    if sp.issparse(matrix):
        data = matrix.data
        row_sums = np.asarray(matrix.sum(axis=1)).ravel()
        nnz = int(matrix.nnz)
    else:
        data = matrix.ravel()
        row_sums = np.asarray(matrix.sum(axis=1)).ravel()
        nnz = int(np.count_nonzero(matrix))
    if data.size == 0:
        data = np.array([0.0])
    sample = data[: min(data.size, 200000)]
    integer_like = float(np.mean(np.isclose(sample, np.rint(sample))))
    return {
        "shape": list(matrix.shape),
        "nnz": nnz,
        "min": float(np.min(data)),
        "max": float(np.max(data)),
        "mean_nonzero": float(np.mean(data)),
        "row_sum_median": float(np.median(row_sums)),
        "integer_like_fraction": integer_like,
    }


def log_norm(matrix):
    if sp.issparse(matrix):
        matrix = matrix.tocsr(copy=True)
        sums = np.asarray(matrix.sum(axis=1)).ravel()
        scale = np.divide(10000.0, sums, out=np.zeros_like(sums, dtype=np.float64), where=sums > 0)
        matrix = sp.diags(scale).dot(matrix).tocsr()
        matrix.data = np.log1p(matrix.data)
        return matrix
    sums = matrix.sum(axis=1)
    scale = np.divide(10000.0, sums, out=np.zeros_like(sums, dtype=np.float64), where=sums > 0)
    return np.log1p(matrix * scale[:, None])


def group_deltas(matrix, guides):
    guides = np.asarray([clean_string(g) for g in guides], dtype=object)
    groups = sorted(g for g in np.unique(guides) if g and not is_nt(g))
    nt_mask = np.array([is_nt(g) for g in guides], dtype=bool)
    if not nt_mask.any():
        raise RuntimeError("No NT controls found")
    nt_mean = np.asarray(matrix[nt_mask].mean(axis=0)).ravel()
    deltas = []
    sizes = {}
    for guide in groups:
        mask = guides == guide
        sizes[guide] = int(mask.sum())
        mean = np.asarray(matrix[mask].mean(axis=0)).ravel()
        deltas.append(mean - nt_mean)
    return groups, np.vstack(deltas), sizes


def zscore_rows(values):
    centered = values - values.mean(axis=1, keepdims=True)
    denom = values.std(axis=1, keepdims=True)
    denom[denom == 0] = 1.0
    return centered / denom


def correlate(ref_delta, query_delta, n_features):
    variance = np.var(np.vstack([ref_delta, query_delta]), axis=0)
    if n_features is not None and n_features < variance.size:
        idx = np.argpartition(variance, -n_features)[-n_features:]
    else:
        idx = np.arange(variance.size)
    ref_z = zscore_rows(ref_delta[:, idx])
    query_z = zscore_rows(query_delta[:, idx])
    corr = query_z.dot(ref_z.T) / float(len(idx))
    return corr, idx


def align_one(ref_guides, ref_targets, ref_delta, query_guides, query_delta, n_features):
    corr, idx = correlate(ref_delta, query_delta, n_features)
    q_ind, r_ind = linear_sum_assignment(-corr)
    assigned = {ref_guides[r]: (query_guides[q], float(corr[q, r])) for q, r in zip(q_ind, r_ind)}
    target_answer = {}
    target_details = {}
    for target in TARGETS:
        ref_for_target = [g for g, t in zip(ref_guides, ref_targets) if clean_string(t).upper() == target]
        if len(ref_for_target) != 1:
            raise RuntimeError(f"Expected one reference guide for {target}, found {ref_for_target}")
        ref_guide = ref_for_target[0]
        ref_idx = ref_guides.index(ref_guide)
        ranked_query = sorted(
            [(query_guides[q], float(corr[q, ref_idx])) for q in range(len(query_guides))],
            key=lambda x: x[1],
            reverse=True,
        )
        query_guide, assigned_corr = assigned[ref_guide]
        target_answer[target] = query_guide
        target_details[target] = {
            "ref_guide": ref_guide,
            "assigned_query": query_guide,
            "assigned_corr": assigned_corr,
            "top_query_by_ref": ranked_query[:8],
        }
    return target_answer, target_details, corr


def main():
    ref_path, query_path, answer_path, diag_path = sys.argv[1:5]
    diag = []
    with h5py.File(ref_path, "r") as ref_h5, h5py.File(query_path, "r") as query_h5:
        ref_obs = read_dataframe(ref_h5["obs"])
        query_obs = read_dataframe(query_h5["obs"])
        ref_guides_cell = np.asarray([clean_string(x) for x in ref_obs["guide"]], dtype=object)
        query_guides_cell = np.asarray([clean_string(x) for x in query_obs["guide"]], dtype=object)
        ref_targets_cell = np.asarray([clean_string(x) for x in ref_obs["target_gene"]], dtype=object)

        matrix_names = ["X"]
        for layer_name in ref_h5.get("layers", {}).keys():
            if layer_name in query_h5.get("layers", {}):
                matrix_names.append(f"layers/{layer_name}")
        diag.append(f"matrix candidates: {matrix_names}")
        diag.append(f"ref guide counts: {dict(pd.Series(ref_guides_cell).value_counts().sort_index())}")
        diag.append(f"query guide counts: {dict(pd.Series(query_guides_cell).value_counts().sort_index())}")

        results = []
        for matrix_name in matrix_names:
            ref_node = ref_h5[matrix_name]
            query_node = query_h5[matrix_name]
            ref_matrix_raw = read_matrix(ref_node)
            query_matrix_raw = read_matrix(query_node)
            diag.append(f"{matrix_name} ref stats: {json.dumps(matrix_stats(ref_matrix_raw), sort_keys=True)}")
            diag.append(f"{matrix_name} query stats: {json.dumps(matrix_stats(query_matrix_raw), sort_keys=True)}")

            variants = [(matrix_name + ":as_is", ref_matrix_raw, query_matrix_raw)]
            stats = matrix_stats(ref_matrix_raw)
            if stats["max"] > 30 or stats["integer_like_fraction"] > 0.98:
                variants.append((matrix_name + ":log1p_cp10k", log_norm(ref_matrix_raw), log_norm(query_matrix_raw)))

            for variant_name, ref_matrix, query_matrix in variants:
                ref_guides, ref_delta, ref_sizes = group_deltas(ref_matrix, ref_guides_cell)
                query_guides, query_delta, query_sizes = group_deltas(query_matrix, query_guides_cell)
                ref_target_lookup = {}
                for guide, target in zip(ref_guides_cell, ref_targets_cell):
                    guide = clean_string(guide)
                    target = clean_string(target)
                    if guide and not is_nt(guide):
                        ref_target_lookup[guide] = target
                ref_targets = [ref_target_lookup[g] for g in ref_guides]
                diag.append(f"{variant_name} ref non-NT guides: {ref_guides}")
                diag.append(f"{variant_name} query non-NT guides: {query_guides}")

                for n_features in [500, 1000, 2000, 5000, None]:
                    answer, details, corr = align_one(
                        ref_guides, ref_targets, ref_delta, query_guides, query_delta, n_features
                    )
                    values = [details[t]["assigned_corr"] for t in TARGETS]
                    score = float(np.mean(values))
                    result = {
                        "variant": variant_name,
                        "n_features": "all" if n_features is None else n_features,
                        "answer": answer,
                        "details": details,
                        "score": score,
                    }
                    results.append(result)
                    diag.append(f"result {variant_name} n_features={result['n_features']}: {json.dumps(result, sort_keys=True)}")

    consensus = defaultdict(list)
    for result in results:
        for target, guide in result["answer"].items():
            consensus[target].append(guide)
    final = []
    for target in TARGETS:
        counts = pd.Series(consensus[target]).value_counts()
        if counts.empty:
            raise RuntimeError(f"No result for {target}")
        top_count = int(counts.iloc[0])
        top_guides = sorted([g for g, c in counts.items() if int(c) == top_count])
        if len(top_guides) != 1:
            raise RuntimeError(f"Ambiguous consensus for {target}: {counts.to_dict()}")
        final.append(top_guides[0])
        diag.append(f"consensus {target}: {counts.to_dict()}")

    with open(answer_path, "w") as handle:
        handle.write(",".join(final) + "\n")
    with open(diag_path, "w") as handle:
        handle.write("\n".join(diag) + "\n")


if __name__ == "__main__":
    main()

